import csv, json
from decimal import Decimal, ROUND_HALF_UP

def r(x, places="0.01"):
    return Decimal(x).quantize(Decimal(places), rounding=ROUND_HALF_UP)

rates = {}
with open("rates.csv") as f:
    for row in csv.DictReader(f):
        rates[row["currency"]] = Decimal(row["eur_per_unit"])

txns = []
with open("transactions.csv") as f:
    for row in csv.DictReader(f):
        eur = r(Decimal(row["amount"]) * rates[row["currency"]])  # round each txn to cent
        txns.append({"month": row["date"][:7], "cat": row["category"], "eur": eur})

cat_tot = {}
mon_tot = {}
for t in txns:
    cat_tot[t["cat"]] = cat_tot.get(t["cat"], Decimal("0")) + t["eur"]
    mon_tot[t["month"]] = mon_tot.get(t["month"], Decimal("0")) + t["eur"]

q2 = sum(mon_tot.values())
def mom(a, b):  # pct change from month a to month b
    return r((mon_tot[b] - mon_tot[a]) / mon_tot[a] * 100, "0.1")

budget = {"travel": 10300, "software": 8200, "hardware": 10700,
          "meals": 3100, "training": 10800, "office": 2200}
over = [c for c in budget if cat_tot[c] > Decimal(str(budget[c]))]

out = {
    "category_totals_eur": {c: float(r(cat_tot[c])) for c in sorted(cat_tot)},
    "q2_total_eur": float(r(q2)),
    "mom_may_pct": float(mom("2026-04", "2026-05")),
    "mom_jun_pct": float(mom("2026-05", "2026-06")),
    "largest_txn_eur": float(r(max(t["eur"] for t in txns))),
    "mean_txn_eur": float(r(q2 / len(txns))),
    "travel_share_pct": float(r(cat_tot["travel"] / q2 * 100, "0.1")),
    "over_budget": sorted(over),
}
with open("RESULTS.json", "w") as f:
    json.dump(out, f, indent=2)
print(json.dumps(out, indent=2))
print("monthly:", {k: str(v) for k, v in sorted(mon_tot.items())}, "n =", len(txns))
EOF
